&lt;p data-path-to-node=&quot;20,2,0&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;Life and disability insurance&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
